package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaBrxDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_breaking_fast" to DuaText("उपबासखौ सिफायनायनि उनाव", "गांनाया जाबाय, रोदाफोरा सिदोब जाबाय, आरो अल्लाहनि गोसो जायोब्ला बान्था रोखा जायो।", "इफ्तारनि समाव।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा गावनि उपबासखौ सिफायनाय समाव बे बाथ्रा बुंदोंमोन।"),
        "dua_new_clothes" to DuaText("गोदान जि गान्नाय।", "ऐ अल्लाह, गासिबो बाख्नायनाया नोंनि; नों आंनो बे गानो। आं नोंखौ बेनि मोजां आरो बेनि मोजांनि थाखाय सोङो जायनि थाखाय बेखौ बानायनाय जादोंमोन, आरो आं नोंनि सिङाव बेनि गाज्रि आरो गाज्रिनिफ्राय रैखा नागिरो जायनि थाखाय बेखौ बानायनाय जादोंमोन।", "गोदान जि गान्नाय समाव (बेखौ मुं दोननाय, जेरै शार्ट एबा पागरा)।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा गोदान जि गान्नाय समाव बे दुआखौ बानायदोंमोन। (गाननायनि थाखाय सानफ्रोमबोनि दुआआ'गान्नाय'नि सिङाव)।"),
        "dua_rabbana_atina" to DuaText("बे मुलुग आरो उनाव मोजां।", "जोंनि इसोर, जोंनो बे मुलुगाव मोजां आरो जोबनायाव मोजां हो आरो जोंनो अरनि साजानिफ्राय रैखा खालाम।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा गोबां समावनो दुआ खालामो।", "मोनसे दुआ जाय बे मुलुग आरो उननि गासैबो मोजांखौ बुथुमो।"),
        "dua_rabbi_zidni_ilma" to DuaText("गियान बांहोनाय।", "आंनि इसोर, आंनो गियानखौ बांहो।", "गियान बांहोनो थाखाय।", "अल्लाहआ पैगंबर (स) खौ गियाननि अनगायै जेबो बांहोनो नाङा होन्ना बिथोन होदोंमोन।"),
        "dua_musa_sharh_sadr" to DuaText("जेरबा गेवनाय (मुसा एएस)", "आंनि इसोर, आंनि थाखाय आंनि जेरबा गोसारहो, आंनि थाखाय आंनि खामानिखौ गोरलै खालाम आरो आंनि खुगानिफ्राय गान्थिखौ बोखार जाहाथे बिसोर आंनि बाथ्राफोरखौ बुजिनो हायो।", "मोनसे आनजाद नायनायनि सिगां, मोनसे बिबुंथि एबा जायखिजाया गोब्राब खामानि।", "पैगंबर मुसा (आ. स.) नि दुआआ-गोसोखौ गोजोन खालामनाय आरो गावनि खामानियाव गोरलै खालामनाय।"),
        "dua_la_tuzigh" to DuaText("बिखानि दिदोमथि", "ऐ जोंनि इसोर, नों जोंनि लामा दिन्थिखांनायनि उनाव जोंनि गोसोफोरखौ सोलायनो नाङा आरो नोंजोंनो जोंनो अनथोब हो। थारैनो, नोंनो सोरखौ मदद होयो।", "बिथोननि सायाव दिदोमथिनि थाखाय।", "फोथायनायाव गोख्रों थानायनि थाखाय मोनसे दुआ।"),
        "dua_ya_muqallib" to DuaText("अ टार्नार अफ हार्ट्स।", "अ'हार्ट्स टर्नर, आंनि गोसोखौ नोंनि धोरोमाव गोख्रों लाखि।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा गोबां समावनो बे दुआखौ खालामोमोन।", "उम्म सलामाह (रा.) नि बायदिब्ला, पैगम्बर सल्लल्लाहु अलैहि वस्लमा गोबां खेब दुआ खालामो।"),
        "dua_la_tuakhidhna" to DuaText("सूराह अल-बकाराहनि जोबथा आयनाफोर।", "ऐ जोंनि इसोर, जों बावगारोब्ला एबा गोरोन्थि खालामब्ला जोंजों जुजिङा। ऐ जोंनि इसोर, जोंनि सायाव ओरैबादि बोदोर दाजा जाय नों जोंनि सिगांनि सुबुंफोरनि सायाव दोनदोंमोन। ऐ जोंनि इसोर, जोंजों बै बोदोर दाजा जाय जों लानो हाया। जोंफोरखौ क्षमा खालाम, नोंखौ क्षमा खालाम आरो जोंनि सायाव अननाय हो। नों जोंनि रैखाथिगिरि, बेनिखायनो फोथायनो हायै सुबुंफोरनि बेरेखायै जोंनि मदद खालाम।", "उन्दुनायनि सिगां हर-सूराह अल-बकाराहनि जोबथा मोन्नै आय'दफोर।", "जाय सोर हरआव सूराह अल-बकाराहनि जोबथा मोन्नै आय'नफोरखौ फरायगोन, बियो थोजासे जागोन।"),
        "dua_visiting_sick" to DuaText("बेरामिया नायहैहै।", "आं नोंखौ फाहामनो थाखाय गोहोगोरा, गोहोगोरा राजउलाफादनि इसोर अल्लाहखौ आरज गाबदों।", "स्नि खेब जेब्ला बेरामिया लोगो नायो।", "थैनायनि समा फैयाब्ला, अल्लाहा बिखौ फाहामगोन।"),
        "dua_ruqyah_pain" to DuaText("देहायारि सानायफोरनि थाखाय", "आं जाय मोन्दांथि मोनो आरो जायखौ गियो बेनि गाज्रिनिफ्राय आं अल्लाह आरो बिथांनि गोहोखौ आश्रय लायो।", "गावनि आखायखौ जेराव सानाय जायो बैयाव दोन, थाम खेब बिस्मिल्लाह बुं, आरो बिनि उनाव स्नि खेब बे दुआखौ हो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेखौ उथमान इब्न अबिल -'आस (रा.) नो सानायखौ फोरोंदोंमोन।"),
        "dua_ruqyah_nabawi" to DuaText("बेरामियाफोरनि थाखाय इयुननि बाथ्रा रकियाह।", "ऐ अल्लाह, मानसिफोरनि इसोर! खहाखौ बोखार आरो फाहामनो हो, मानोना नोंनो फाहामग्रा; नोंनि फाहामनायनि अनगा जेबो फाहामनाय गैया-मोनसे फाहामनाय जाय जेबो बेरामखौ नागाराखै।", "बेराम जानाय सुबुंनि सायाव आखाय हगारनाय समाव।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा गावनि नखरनि बेरामगोनां सोद्रोमाफोरखौ लोगो हमनायाव बेखौ फरायदोंमोन।"),
        "dua_kalimat_tammat" to DuaText("आबुं सोदोबफोराव शरण नागिरनाय।", "आं अल्लाहनि आबुं सोदोबफोराव बिथांनि सोरजिनाय गाज्रिनिफ्राय रैखा नागिरो।", "जेब्ला मोनसे जायगायाव एबा बेलासियाव थाद'यो।", "जाय मोनसे जायगायाव थाद'यो आरो बेबादि बुङो, बियो बेखौ नागारजासिम जेबो खहा खालामै।"),
        "dua_evil_eye" to DuaText("गथ'फोरनि थाखाय रैखाथि (गाज्रि मेगन)", "आं गासिबो शय़तान आरो बिसगोनां जिबफोरनिफ्राय आरो गासिबो खहा खालामग्रा मेगननिफ्राय नोंनि थाखाय अल्लाहनि आबुं सोदोबफोराव रैखाथि नागिरो।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बे बाथ्राखौ हसन आरो हुसैननि सायाव फरायदोंमोन।", "गथ'फोरखौ गाज्रि मेगन आरो खहा जानायनिफ्राय रैखा खालामनो थाखाय मोनसे सुन्नत दुआ (सासे गथ'नि थाखाय'उधुका')।"),
        "dua_seeing_afflicted" to DuaText("सोरबा सासेखौ बिजिरनायाव नाय।", "गासिबो बाख्नायनाया अल्लाहनि थाखाय जाय नोंखौ जायजों आनजाद नायदोंमोन बेनिफ्राय आंखौ बासायो आरो गावनि गोबां सोरजिलुनि सायाव आंखौ मोजां मोनो।", "सोरबा सासेखौ बिसावरियाव नायब्ला (बेखौ गावनो सिरिङै बुं)।", "जाय बुङो बियो बै बिजिरनायनिफ्राय रैखाथि होजायो।"),
        "dua_istikhara" to DuaText("सालात अल-इस्तिकारा", "ऐ अल्लाह, आं नोंनि गियाननि गेजेरजों मोजांखौ नागिरो, आं नोंनि गोहोनि गेजेरजों रोंग'थि नागिरो, आरो आं नोंनि गिदिर अनथोबखौ सोंनो। नोंहा गोहो दं आरो आंनाव जेबो गैया। नों मिथियो आरो आं गैया, आरो नों नायजायैनि गियान। ऐ अल्लाह, जुदि नोंनि गियानाव बे बाथ्राया (बेखौ गोसोआव लाबो) आंनि धोरोम, आंनि जिउ आरो आंनि जोबथा थाखाय मोजां, अब्ला आंनि थाखाय बेखौ बिथोन हो, आंनि थाखाय बेखौ गोरलै खालाम आरो बेयाव आंखौ बोर हो। आरो जुदि नोंनि गियानाव बे बाथ्राया आंनि धोरोम, आंनि जिउ आरो आंनि जोबथा थाखाय गाज्रि, अब्ला बेखौ मोनिफ्राय बोखार आरो आंनिफ्राय गोजानाव हो आरो जेरावबो मोजां जानो हागौ, अब्ला आंनो बेजों गोजोन हो।", "गावबागाव आरज गाबनायनि मोननै राकाफोरनि उनाव, मोनसे गनायथि होजानाय बिथिङाव साबसिनखौ नागिरना ला।", "पैगम्बर स'लिअल्लाहअलिह वसलमा लोगोफोरनो गासिबो बिथिङाव इस्तिकारा फोरोंदोंमोन मानोना बिथाङा बिसोरखौ कुराननि मोनसे सूराह फोरोंदोंमोन।"),
        "dua_allahumma_bika_asbahna" to DuaText("अल्लाहुम्मा बीका असबाहना", "ऐ अल्लाह, जों नोंनि गेजेरजों फुंआव हाबलाङो आरो नोंनि गेजेरजों बेलासियाव हाबलाङो; जों नोंनि गेजेरजों थांना थायो आरो जों नोंनि गेजेरजों थैयो, आरो नोंनि थाखाय पुनरुत्थान।", "फुंआव।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा लोगोफोरखौ दिनै फुं आरो बेलासियाव बुंनो फोरोंदोंमोन।"),
        "dua_allahumma_bika_amsayna" to DuaText("अल्लाहुम्मा बीका अम्सेना", "ऐ अल्लाह, जों नोंनि दारै बेलासियाव हाबलाङो आरो नोंनि दारै फुंआव हाबलाङो; जों नोंनि दारै थांना थायो आरो नोंनि दारै थैयो, आरो नोंनि दारै फैफिनो।", "बेलासियाव।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा लोगोफोरखौ दिनै फुं आरो बेलासियाव बुंनो फोरोंदोंमोन।"),
        "dua_afiyah_morning" to DuaText("आफियाहखौ सोंनाय", "ऐ अल्लाह, आं नोंखौ बे मुलुग आरो उनाव क्षमा आरो मोजांनि थाखाय आरज गाबदों।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बे दुआखौ माब्लाबाबो, फुं एबा बेलासियाव नागाराखैमोन।", "सोरखौबो मोजांनिख्रुइ साबसिन जेबो होनाय जायाखै।"),
        "dua_afini_fi_badani" to DuaText("देहानि सावस्रि, खोनानाय आरो नुथाइ", "ऐ अल्लाह, आंनि देहाखौ मोजां खालाम। ऐ अल्लाह, आंनि खोनानो हानायखौ मोजां खालाम। ऐ अल्लाह, आंनि मेगनखौ मोजां खालाम। नोंनि अनगायै रावबो इसोर गैया।", "सानसेखालि फुं आरो बेलासियाव खेबथाम।", "सावस्रि आरो मोनदांथिफोरनि रैखाथिनि थाखाय मोनसे दुआ।"),
        "dua_ya_hayyu_aslih" to DuaText("आंनि गासैबो आयदाफोरखौ फोसाब।", "ऐ अराय जिउगोनां, ऐ खांग्रा, आं नोंनि अननायजों मदद नागिरो; आंनि गासिबो हाबाफोरखौ थि खालाम आरो आंखौ मेगन मोख्लाबनायसिमबो आंनावनो नागारनाङा।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा फातिमा (रा.) खौ बेखौ फुं आरो बेलासियाव बुंनो बोसोन होदोंमोन।", "गासैबो बिथिङाव अल्लाहनि मदद ला।"),
        "dua_subhanallah_adada_khalqihi" to DuaText("जुवेरियानि तसबीह (आर. ए.)", "अल्लाहनो गोगाथाव आरो गासिबो बाख्नायनाया बिथांनि-बिथांनि सोरजिलुनि समान, जेसेबां बिथांखौ गोजोनहोयो, बिथांनि राजउलाफादनि गिलिर आरो बिथांनि सोदोबफोरनि मैसिनि समान।", "फुंनि खेबथाम-घन्तानि घन्तानिख्रुइ गिलिरसिन।", "बे मोनब्रै सोदोबफोरखौ खेबथाम बुंनाया फुंनिफ्राय मध्य-फुंसिम धिकरखौ बारायो।"),
        "dua_salawat" to DuaText("दुरूद-ए-इब्राहिमि", "ऐ अल्लाह, मुहम्मद (स) आरो मुहम्मद (सा) नि नखरनि सायाव आरज हर, जेरै नोंथाङा इब्राहिम (सा) आरो इब्राहिमनि नखरनि सायाव आरज गाबदोंमोन; नोंथाङा बाखनायजाथाव, गोग्गानाय। ऐ अल्लाह, मुहम्मद (सा) आरो मुहम्मद (सा) नि नखरखौ बोर हो जेरै नोंथाङा इब्राहिम (सा) आरो इब्राहिमनि नखरखौ बोर होदोंमोन; नोंथाङा बाखनायजाथाव, गोग्गानाय।", "पैगंबर सल्लल्लाहु अलैहि वस्लमनि सायाव सालावतखौ आरज गाबनायाव आरो जेब्लाबो।", "जाय सासेया खनसे सालावत दैथायहरो, अल्लाहआ बिनि सायाव जि अननाय हरो (मुस्लिम 408)।"),
        "dua_wudu_after" to DuaText("वुडूनि उनाव", "आं साखि होयो दि अल्लाहनि अनगा रावबो फुजिजानायनि मोन्थाइ गैया, सोलायै, बाहागोआरि गैयालासे, आरो मुहम्मद सलिहआ बिथांनि बान्दा आरो रसूला। ऐ अल्लाह, आंखौ बैसोरफोरनि गेजेराव बानाय जाय गोसो बावसोमनाय आरो गावखौ गोथार खालामनाय।", "वुडूखौ फोजोबनायनि उनाव।", "सोरगोनि दाइन दरजाखौ बिनि थाखाय खेवनाय जायो जेराव बियो गोसो जायो।"),
        "dua_wudu_before" to DuaText("वुडूनि सिगां", "अल्लाहनि मुंजों।", "जेब्ला वुडुखौ जागायो।", "जाय बेनि सायाव अल्लाहनि मुंखौ मुंख'यो बिनि थाखाय जेबो (आबुं) वुडू गैया।"),
        "dua_istiftah" to DuaText("बेखेवनाय आरज (सना)", "हे अल्लाह, नोंनो महिमा आरो नोंनो बाख्नायनाय। नोंनि मुङा बाख्नायजानाय, नोंनि महिमाआ बाख्नायजानाय, आरो नोंनि अनगायै रावबो इसोर गैया।", "आरज गाबनायनि जागायनायाव, खेवनाय तकबीरनि एसे उनाव।", "सुन्नाहआ आरज गाबनायनि दुआखौ खुलि।"),
        "dua_ruku" to DuaText("रुकुवाव", "आंनि इसोरनो, गेदेमाखौ गोग्गानाय।", "रुकुवाव खमैबो खेबथाम।", "रुकुनि सुन्नह तासबिह।"),
        "dua_sujood" to DuaText("सुजूदआव", "आंनि इसोर, गोजौसिन, नो गोग्गांथि।", "सुजूदआव खमैबो खेबथाम।", "बान्दाआ साथा गाबनाय समाव गावनि इसोरनि खाथिसिनसिन (मुस्लिम 482)।"),
        "dua_rising_ruku" to DuaText("रुकुनिफ्राय ओंखारनाय।", "अल्लाहआ बैसोरखौ खोनासङो जाय बिखौ बाख्नायो। जोंनि इसोर, गासिबो बाख्नायनाया नोंनो।", "रुकुनिफ्राय ओंखारनानै थोंगोर गसंना थानाय समाव।", "जाय'रब्बाना वा लकल-हमद'आ फेरेशतफोरजों गोरोबो, बिनि सिगांनि पापफोरखौ माफ खालामनाय जायो।"),
        "dua_between_sajdas" to DuaText("सानै साजदासनि गेजेराव", "आंनि इसोर, आंखौ बावगार। आंनि इसोर, आंखौ बावगार।", "मोन्नै साथा-साथाफोरनि गेजेराव जिरायना थानाय समाव।", "साथा-साथाफोरनि गेजेराव जिरायनायनि सुन्नत दुआ।"),
        "dua_before_salam_four" to DuaText("मोनब्रै बाथ्राफोरनिफ्राय रैखा खालाम (सालामनि सिगां)", "ऐ अल्लाह, आं जाहान्नामनि साजा, गोथै खाम्फानि साजा, जिउ आरो थैनायनि आनजाद आरो गोरोन्थि मसीहा (दज्जल) नि बिजिरनायनि गाज्रिनिफ्राय नोंखौ शरण लायो।", "जोबथा ताशाहहुद आरो सालावतनि उनाव, सालामनि सिगां।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बे मोनब्रै बाथ्राफोरनिफ्राय आश्रय लानो बिथोन होदोंमोन।"),
        "dua_qunoot_witr" to DuaText("कुनुत इन विटर", "ऐ अल्लाह, आंनो बैसोरनि गेजेराव लामा दिन्थि, जायफोरखौ नों मोजां होदों, आंनो मोजां राहा हो, आरो जायफोरा नों गावनि जोथोनाव लादोंमोन, बिसोरनि गेजेराव आंनो गावनि जोथोनाव ला, नों जायखौ होदों, बेफोराव आंखौ बर'द हो आरो नों जायखौ बिथोन होदों, बिनि गाज्रिनिफ्राय आंखौ रैखा खालाम। नों बिथोन होयो आरो नोंनि बेरेखायै जेबो बिथोन गैया, आरो जायजों नों लोगो दं, बियो माब्लाबाबो लाजि जानाय नङा। बोरगोनां आरो गोजौसिन नों, जोंनि रब।", "विदर आरजआव-पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेखौ हसन इब्न अली (रा.) नो फोरोंदोंमोन।", "विदरनि सुन्नत कुनूत। (हनाफीफोरनि गेजेराव,'अल्लाहुम्मा इन्ना नास्ताइनुका'बो मुंदांखा।)"),
        "dua_qunoot_hanafi" to DuaText("कुनूत (अल्लाहुम्मा इन्ना नास्ताइनुका)", "ऐ अल्लाह, जों नोंनि मदद आरो नोंनि आरजखौ नागिरो, जों नोंखौ फोथायो आरो नोंनि सायाव सोनारना थायो, जों नोंखौ साबसिन रोखोमै बाख्नायो, जों नोंखौ बाख्नायो आरो अनजाथाव नङा, आरो जों जायखौ नोंखौ मानियाङो बिखौ नागारो। ऐ अल्लाह, जों नोंखौल'आराफायो, नोंखौ सिबिनाय आरो सिबिनाय खालामो, जों नोंखौ गोख्रै आरो जुजिनो, जों नोंनि अननायनि मिजिं खालामो आरो नोंनि सजाखौ गियो; थारैनो नोंनि साजाआ फोथायजायैफोरसिम सौहैगोन।", "विदरआव-हनाफिफोरनि हुदा।", "कुनूतआव उमर (र.) निफ्राय फोरमायथि होजादोंमोन।"),
        "dua_sleep_aslamtu" to DuaText("उनदुनो सिगां जोबथा सोदोबफोर", "ऐ अल्लाह, आं नोंखौ गावखौ बावनाय, आंनि हाबाखौ नोंनो हो आरो आंनि बिखुंखौ नोंनि रैखाथिआव हो, नोंनि सायाव मिजिं आरो नोंनि सायाव गिनांगौ। नोंनि अनगायै जेबो आश्रय आरो नोंनिफ्राय बारग'नाय गैया। आं नोंनि बिजाबाव फोथायो जायखौ नों फोसावदोंमोन आरो नोंनि पैगंबराव जायखौ नों हर हरदोंमोन।", "वुडूनि उनाव, आगदा फारसे सिरि-उन्दुनायनि सिगां जोबथा सोदोब।", "जुदि बियो बै मोनायाव थैयो, अब्ला बियो फित्रायाव (इस्लाम) थैयो।"),
        "dua_waking_night" to DuaText("हराव जागो।", "अल्लाहनि अनगा रावबो फुजिजानायनि मोन्थाइ गैया, सोलायै, बाहागोआरि गैयालासे। बिथांनिनो रायजो आरो बिथांनिनो बाख्नायनायनाय, आरो गासिबो जिनिसनि सायाव बिथांनि गोहो दं। गासिबो बाख्नायनाया अल्लाहनि थाखाय, अल्लाहनि थाखाय बाख्नायनायनाय, अल्लाहनि अनगा रावबो फुजिजानायनि मोन्थाइ गैया, अल्लाहानो देरसिन, आरो अल्लाहनि अनगा जेबो गोहो एबा गोहो गैया। ऐ अल्लाह, आंखौ क्षमा खालाम।", "हराव उन्दुयोब्ला।", "बिथांनि दुआनि फिन होनाय जायो, आरो जुदि बिथाङा वुडू खालामो आरो आरज गाबो, अब्ला बिथांनि आरजखौ गनायनाय जायो।"),
        "dua_hamm_ibn_masud" to DuaText("दुखनि थाखाय दुआ (इब्न मसूद)", "ऐ अल्लाह, आं नोंनि बान्दा, नोंनि बान्दा, नोंनि दासिनि फिसाज्ला, नोंनि दासिनि फिसाज्ला। आंनि फारलकआ नोंनि आखायाव दं, आंनि सायाव नोंनि बिथोनखौ मावनाय जायो, आरो आंनि सोमोनदै नोंनि बिथोनआ न्यायगोनां। आं नोंखौ गासिबो मुंजों सोङो जायजों नों गावनि मुं दोनदोंमोन, एबा नोंनि बिजाबाव फोसावजादोंमोन, एबा नोंनि सोरजिनानि जायखिजायाखौ फोरोंदोंमोन, एबा नायजायैनि गियानाव नोंजोंनो दोनजादोंमोन-दि नों कुरानखौ आंनि बिखानि उदां, आंनि जेरबा सोरां, आंनि दुखुखौ बोखारनाय आरो आंनि जिंगाखौ नागारनाय।", "दुखु आरो दुखुआव-अल्लाहआ दुखुखौ गोजोनजों सोलायहोयो।", "अल्लाहआ बिथांनि जिंगाखौ आरो दुखुखौ बोखारो आरो बिखौ बेनि जायगायाव गोजोन होयो।"),
        "dua_difficulty_sahl" to DuaText("जेब्ला माबा मोनसेआ गोब्राब जायो।", "ऐ अल्लाह, जायखौ नों गोरलै खालामो बेनि अनगा जेबो गोरलै नङा, आरो नों लुबैदोंब्ला गोब्राबखौ गोरलै खालामो।", "जेब्ला माबा मोनसेआ गोब्राब मोनो।", "आनजादफोराव गोरलै आरो गोब्राब खामानिफोर।"),
        "dua_musibah" to DuaText("आफाउन ए केलेमिटी (इस्तिरजा)", "जों अल्लाहनि आरो जों बिनिनो फैफिनो। ऐ अल्लाह, आंनि दुखुआव आंनो बान्था हो आरो बिनि जायगायाव आंनो साबसिन माबा मोनसे हो।", "जायखिजाया खहा एबा खैफोदआव।", "अल्लाहआ थारैनो साबसिन माबा होयो-उम्म सलामाह (रा) खौ पैगम्बर सल्लल्लाहु अलैहि वस्लम होनाय जादोंमोन।"),
        "dua_debt" to DuaText("दाहारनिफ्राय रैखा मोननो थाखाय", "ऐ अल्लाह, नों जायखौ आयेन गैयै खालामदोंमोन बिनि बेरेखायै नों जायखौ गनायथि होदों, बियो थोजासे आरो नोंनि अनथोबजों आंनो नोंनि अनगायै गासिबोनिफ्राय उदां खालाम।", "दाहार सुख'नो थाखाय-आली (आर. ए.) जों फोरोंनाय।", "दाहारआ हाजो बायदिब्लाबो, अल्लाहा बेखौ फोजोबगोन।"),
        "dua_anger" to DuaText("जेब्ला रागा जोंख्लैयो।", "आं शापित शयताननिफ्राय अल्लाहनि शरण लायो।", "जेब्ला रागा जोंख्लैयो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बुङोः जुदि बियो बेबादि बुङो, अब्ला बिथांनि रागाआ खारगोन।"),
        "dua_waswasa" to DuaText("फोथायनायाव वासवासानि बेरेखायै।", "आं अल्लाह आरो बिथांनि रसूलाफोरखौ फोथायो।", "जेब्ला फोथायनायनि बागै शेताननि फिसारनाया फैयो।", "जेब्ला फिसारआ फैयो, अब्ला बे बाथ्रा बुं आरो बैयावनो थाथ'(आरो अल्लाहनि शरणाबो ला)।"),
    )
}
